// Extract incoming webhook payload
const data = $input.first().json;

const email = (data.email || '').trim().toLowerCase();
const otp = String(data.otp || '').trim();
const institution = data.institution_name || 'Anantha Lakshmi Institute of Technology and Sciences';
const role = data.role || 'Faculty';
const purpose = data.purpose || 'Institutional Portal Login Verification';
const expiryMinutes = data.expires_in_minutes || 5;
const subject = data.subject || `🔐 [${institution}] Your Verification Passcode: ${otp}`;

if (!email || !otp) {
  throw new Error('Invalid payload: email and otp are required.');
}

// Generate clean, modern, responsive HTML email template
const htmlBody = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${subject}</title>
  <style>
    body { margin: 0; padding: 24px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f1f5f9; }
    .wrapper { max-width: 560px; margin: 0 auto; background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); overflow: hidden; }
    .header { background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 100%); padding: 28px 24px; text-align: center; color: #ffffff; }
    .header h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: -0.02em; }
    .header p { margin: 6px 0 0; font-size: 13px; color: #bfdbfe; }
    .badge-bar { background: #0f172a; padding: 8px 16px; text-align: center; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #38bdf8; font-weight: 600; }
    .content { padding: 32px 28px; text-align: center; color: #1e293b; }
    .purpose-text { font-size: 15px; line-height: 1.5; color: #475569; margin: 0 0 20px; }
    .otp-container { background: #eff6ff; border: 2px dashed #60a5fa; border-radius: 10px; padding: 18px 24px; margin: 24px 0; display: inline-block; }
    .otp-code { font-family: 'Courier New', monospace; font-size: 40px; font-weight: 800; letter-spacing: 10px; color: #1d4ed8; margin: 0; }
    .expiry-note { font-size: 13px; color: #64748b; margin: 16px 0 0; }
    .details-box { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 14px 18px; margin-top: 24px; text-align: left; font-size: 12px; color: #475569; }
    .details-box p { margin: 4px 0; }
    .security-notice { margin-top: 20px; font-size: 12px; color: #dc2626; background: #fef2f2; border: 1px solid #fee2e2; border-radius: 6px; padding: 10px 14px; text-align: left; }
    .footer { background: #f8fafc; border-top: 1px solid #e2e8f0; padding: 16px 20px; text-align: center; font-size: 11px; color: #94a3b8; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <h1>${institution}</h1>
      <p>Automated Institutional Compliance & Document Audit System</p>
    </div>
    <div class="badge-bar">
      ⚡ Powered by n8n Automated Email Delivery
    </div>
    <div class="content">
      <p class="purpose-text">${purpose}</p>
      <div class="otp-container">
        <div class="otp-code">${otp}</div>
      </div>
      <p class="expiry-note">⏱️ This passcode is valid for <strong>${expiryMinutes} minutes</strong> and can only be used once.</p>
      <div class="details-box">
        <p><strong>Account Recipient:</strong> ${email}</p>
        <p><strong>Authorized Role:</strong> ${role}</p>
        <p><strong>Audit System Host:</strong> Automated Compliance Server</p>
      </div>
      <div class="security-notice">
        ⚠️ <strong>Security Advisory:</strong> Institutional staff will never ask for your verification code. Do not disclose this code to anyone.
      </div>
    </div>
    <div class="footer">
      This is an automated institutional compliance notification &bull; ${institution}
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    email,
    otp,
    institution,
    role,
    purpose,
    subject,
    html: htmlBody,
    expiryMinutes,
    timestamp: new Date().toISOString()
  }
}];
